import unittest

from solucao import pegar
from solucao import total_do_comeco


class TestPegarPelaPosicao(unittest.TestCase):
    def test_pega_o_primeiro(self):
        """pegar devolve o item da posicao 0"""
        self.assertEqual(pegar([["ana", 10], ["bia", 20]], 0), ["ana", 10])

    def test_pega_o_ultimo(self):
        """pegar devolve o item da ultima posicao"""
        self.assertEqual(pegar([["ana", 10], ["bia", 20], ["caio", 30]], 2), ["caio", 30])

    def test_total_dos_dois_primeiros(self):
        """total_do_comeco devolve a soma dos dois primeiros"""
        self.assertEqual(total_do_comeco([10, 20, 30]), 30)

    def test_total_de_uma_lista_de_dois(self):
        """total_do_comeco devolve 12 para a lista [5, 7]"""
        self.assertEqual(total_do_comeco([5, 7]), 12)

